import{_ as o,l,o as e,c as s,v as t,p as i,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"业绩费与高水位","description":"","frontmatter":{"title":"业绩费与高水位","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/performance-fee-hwm.md","filePath":"quant/performance-fee-hwm.md","lastUpdated":1789023840000}'),c={name:"quant/performance-fee-hwm.md"};function m(u,a,E,f,B,_){const n=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="业绩费与高水位" tabindex="-1">业绩费与高水位 <a class="header-anchor" href="#业绩费与高水位" aria-label="Permalink to &quot;业绩费与高水位&quot;">​</a></h1><div class="epigraph"><p>高水位把管理人的激励费变成对净值路径的看涨：只有越过历史峰值才收费；期权的价值随波动上升，于是费率条款本身会改变愿意承担的风险。</p><footer>—— Goetzmann, Ingersoll and Ross, High-Water Marks and Hedge Fund Management Contracts, Journal of Finance, 2003</footer></div><p><a href="/quant/strategy-lifecycle">上一课</a>收口策略会衰减。业绩单元的缺口是<strong>谁从剩下的 P&amp;L 里先拿走一截</strong>。管理费是对 AUM 的固定抽成；激励费常带高水位（HWM）：净值创出新高才计提。本课写条款如何改变风险激励，以及投资人看到的净收益为何不是毛收益乘以 (1−20%)。主干 <a href="/quant/ir-sharpe">IR/Sharpe</a> 在扣费对象上必须对齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Goetzmann–Ingersoll–Ross 把 HWM 写成或有要求权：管理人持有对基金净值的看涨，执行价是当前水位。波动上升提高期权价值，于是在水位以下时，管理人有动机加大风险去「搏回来」，或在无望时放弃努力（关闭基金、另开一只以重置水位）。问题是治理：条款要与锁定期、赎回、自有资本一起看，不能单独谈「2 和 20」。Panageas–Westerfield 等后续工作讨论即使无管理费，HWM 下的风险选择也不是简单的「总是赌博」。</p><p>与策略地图：短波动卖方的左尾会长期停在水位下，激励费为零，管理费仍抽；投资人此时付的是期权费加管理费，不是「没赚钱就不收费」。</p><h3 id="均衡水位与基金关闭" tabindex="-1">均衡水位与基金关闭 <a class="header-anchor" href="#均衡水位与基金关闭" aria-label="Permalink to &quot;均衡水位与基金关闭&quot;">​</a></h3><p>水位远高于净值时，激励费的 delta 接近零，管理人与投资人的利益最分叉。重置水位（新基金、合并、协商打折）是隐性再谈判。回测若用固定 20% 激励、从不重置、从不关闭，会高估投资人净收益的左尾保护。</p><p><span class="marginnote">水晶条款（clawback）、均衡化（equalization）和系列份额是为了不同时点申购者之间的公平，不是为了提高夏普。忽略它们会把费用算错到份额层面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合同：管理费、激励费、HWM、 hurdle、结晶频率、clawback。会计：按日净值路径模拟费用，而不是按年收益×20%。对照：同一毛路径在不同波动下的净路径。风险：水位下的杠杆政策必须事先写进产品备忘，不能事后当择时。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>激励费是路径依赖的看涨。投资人卖出这笔期权，换来「有技能才付」。技能若不可持续（后课），期权费是纯转移。HWM 保护投资人免于对同一块净值重复付激励，但不保护管理费，也不保护水位下的赌博。</p>',13)),(e(),i(p,null,{default:r(()=>[h(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAV%5B%22%E5%87%80%E5%80%BC%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20HWM%5B%22%E9%AB%98%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20HWM%20--%3E%20Call%5B%22%E6%BF%80%E5%8A%B1%E8%B4%B9%E5%A6%82%E7%9C%8B%E6%B6%A8%22%5D%0A%20%20Vol%5B%22%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20Call%0A%20%20UW%5B%22%E6%B0%B4%E4%BD%8D%E4%BB%A5%E4%B8%8B%22%5D%20--%3E%20Risk%5B%22%E9%A3%8E%E9%99%A9%E6%BF%80%E5%8A%B1%E5%88%86%E5%8F%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何设计合同去规避监管或误导披露。税务对激励费的处理因辖区而异。下一课把管理费与激励费一起放进复利。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>高水位使激励费成为路径依赖期权，改变风险激励。</li><li>水位以下管理费仍在抽；净收益不是毛收益×0.8。</li><li>关闭与重置水位是隐性再谈判，回测要包含。</li><li>出处：Goetzmann, Ingersoll and Ross, <em>JF</em>, 2003；后续风险选择见 Panageas and Westerfield 等。</li></ul>',4))])}const b=o(c,[["render",m]]);export{q as __pageData,b as default};
